<script setup lang="ts">
import { computed, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { teamService } from '@/services/team'
import { demoMode, request } from '@/services/quality'
const route = useRoute(); const router = useRouter(); const busy = ref(false); const error = ref(''); const done = ref(false)
const signedIn = ref(Boolean(sessionStorage.getItem('bestpharma.token')))
const existing = ref(signedIn.value)
async function disconnect() { busy.value = true; try { await request('/auth/logout', 'POST'); sessionStorage.removeItem('bestpharma.token'); sessionStorage.removeItem('bestpharma.officine'); sessionStorage.removeItem('bestpharma.platform'); signedIn.value = false; existing.value = false } catch(e) { error.value = (e as Error).message } finally { busy.value = false } }
const token = computed(() => new URLSearchParams(route.hash.slice(1)).get('token') || '')
const form = reactive({ name: '', email: '', password: '', password_confirmation: '' })
const next = computed(() => `/invitation#token=${encodeURIComponent(token.value)}`)
async function accept() {
 error.value = ''
 if (!demoMode && !existing.value && (form.password !== form.password_confirmation || !/[A-Za-z]/.test(form.password) || !/\d/.test(form.password))) { error.value = 'Les mots de passe doivent être identiques et contenir des lettres et des chiffres.'; return }
 busy.value = true
 try { await teamService.accept({ token: token.value, name: form.name, email: form.email, ...(!existing.value && !demoMode ? { password: form.password, password_confirmation: form.password_confirmation } : {}) }); form.password = ''; form.password_confirmation = ''; done.value = true; await router.replace('/invitation') }
 catch(e) { error.value = (e as Error).message } finally { busy.value = false }
}
</script>
<template><div class="registration-page"><header><RouterLink class="brand" to="/login">bestpharma.</RouterLink><span class="eyebrow">REJOINDRE UNE OFFICINE</span></header><main class="registration-content"><p class="eyebrow">UNE INVITATION POUR VOUS</p><h1>Une équipe,<br><span class="accent-serif">un même engagement.</span></h1><p v-if="demoMode" class="alert">Simulation locale : utilisez l’adresse fictive de l’invitation. Aucune identité n’est réellement vérifiée dans cet aperçu.</p><div v-if="done" class="panel empty-state"><h2>Invitation acceptée</h2><p>Votre compte a rejoint l’officine avec les droits attribués par son administrateur.</p><RouterLink class="button primary" :to="demoMode ? '/equipe' : '/dashboard'">{{ demoMode ? 'Voir le membre ajouté' : 'Ouvrir mon officine' }}</RouterLink></div><section v-else-if="!token" class="panel empty-state"><h2>Lien d’invitation manquant</h2><p>Ouvrez le lien transmis par l’administrateur de l’officine.</p></section><form v-else class="panel" @submit.prevent="accept"><div class="form-body"><p v-if="error" role="alert" class="alert error">{{ error }}</p><h2>Rejoindre l’officine</h2><button v-if="signedIn && !demoMode" type="button" class="button secondary self-start" :disabled="busy" @click="disconnect">Déconnecter le compte actuel</button><p class="field-hint">Le lien est personnel, valable 7 jours et utilisable une seule fois. Les droits sont définis par l’administrateur et ne peuvent pas être changés ici.</p><label>Adresse e-mail invitée *<input v-model.trim="form.email" type="email" required maxlength="254" autocomplete="email" /></label><label v-if="!demoMode" class="checkbox-label"><input v-model="existing" type="checkbox" /><span>J’ai déjà un compte BestPharma</span></label><template v-if="!existing || demoMode"><label>Nom et prénom {{ demoMode ? 'fictifs' : '' }} *<input v-model.trim="form.name" required maxlength="120" autocomplete="name" /></label><div v-if="!demoMode" class="form-grid"><label>Mot de passe *<input v-model="form.password" type="password" minlength="12" maxlength="128" autocomplete="new-password" required /></label><label>Confirmation *<input v-model="form.password_confirmation" type="password" minlength="12" maxlength="128" autocomplete="new-password" required /></label></div></template><div v-else class="review-note"><p>Connectez-vous avec le compte correspondant à cette invitation, puis revenez ici pour confirmer.</p><RouterLink class="text-link" :to="{path:'/login',query:{next}}">Se connecter au compte invité →</RouterLink></div></div><div class="modal-footer"><button class="button primary" :disabled="busy">{{ busy ? 'Vérification…' : 'Accepter l’invitation' }}</button></div></form></main></div></template>
